import { DashboardView } from "../../../src/views/DashboardView";

/**
 * Wrapped rather than re-exported.
 *
 * `DashboardView` takes an optional props object, so its first parameter is
 * `{ dataState?: … } | undefined`. Next's generated page-type check requires a
 * page's first parameter to satisfy `PageProps`, and `undefined` does not —
 * `export { DashboardView as default }` therefore failed the web type-check.
 * The failure only appears once `.next/dev/types` has been generated by a dev
 * run, which is why a clean CI checkout stayed green.
 */
export default function DashboardPage() {
  return <DashboardView />;
}
